      "lyrics": [
        "誰もみんな消えてく夢を見た",
        "真夜中の部屋の広さと静寂が",
        "胸につっかえて",
        "上手に息ができなくなる"
      ]
    },
    {
      "section": "C3",
      "lyrics": [
        "核融合炉にさ",
        "飛び込んでみたらそしたら",
        "きっと眠るように消えていけるんだ",
        "僕のいない朝は",
        "今よりずっと素晴らしくて",
        "全ての歯車が噛み合った",
        "きっとそんな世界だ"
      ]
