      "phrases": [
        {
          "id": "C3-01",
          "zh": "在那核聚变炉边"
        },
        {
          "id": "C3-02",
          "zh": "我飞身跃入其中去试试看"
        },
        {
          "id": "C3-03",
          "zh": "一定会像睡着那样静静地消散了啊"
        },
        {
          "id": "C3-04",
          "zh": "那一个没有我清早啊"
        },
        {
          "id": "C3-05",
          "zh": "一定会比现在更加美好多啊"
        },
        {
          "id": "C3-06",
          "zh": "所有的齿轮都完美地咬合上啦"
        },
        {
          "id": "C3-07",
          "zh": "一定是那样世界啊"
        }
